#pragma once
#include "link_evidence.hpp"
#include <array>
#include <cmath>
#include <stdexcept>

namespace rfmon::cyclo {
inline constexpr const char* named_link_catalogue_version="named_link_research_catalogue_v1";
struct NamedLinkProfile {
    const char* id;
    double slope,sweep;
};
// Cwalina et al., Sensors 2025, DOI 10.3390/s25154552, section 2.
// A match is compatible with a reported OcuSync-related marker, not unique
// protocol evidence. These chirps can be generated by unrelated transmitters.
inline constexpr std::array<NamedLinkProfile,3> ocusync_marker_profiles{{
    {"up_9mhz",135.2e9,9e6},{"up_18mhz",270.2e9,18e6},{"down_9mhz",-135.3e9,9e6}}};
struct NamedLinkCandidate {
    const char* family="DJI OcuSync";
    const char* scope="reported_chirp_marker_compatibility_only";
    const char* profile="";
    const char* status="unavailable";
    std::size_t measurement_index=0,offset=0,samples=0;
    bool marker_compatible=false;
    std::array<const char*,10> blockers{};
    std::size_t blocker_count=0;
};
struct NamedLinkCandidates {
    std::array<NamedLinkCandidate,3> candidates{};
    std::size_t count=0;
};
inline NamedLinkCandidates assess_named_link_candidates(const SpectralFeatures& spectral,
    const std::vector<ChirpMeasurement>& chirps,const EvidenceContext& context,std::size_t samples) {
    if(chirps.size()>3 || samples>65536)throw std::invalid_argument("named candidate bounds");
    const auto evidence=assess_link_evidence(spectral,{},chirps,context);
    NamedLinkCandidates out;
    for(std::size_t index=0;index<chirps.size();++index) {
        const auto& m=chirps[index];const NamedLinkProfile* profile=nullptr;
        for(const auto& p:ocusync_marker_profiles)
            if(m.slope_hz_per_second==p.slope && m.nominal_sweep_hz==p.sweep)profile=&p;
        if(!profile)continue; // Never infer family from a caller-supplied label.
        auto& candidate=out.candidates[out.count++];candidate.profile=profile->id;candidate.measurement_index=index;
        auto block=[&](const char* s){candidate.blockers[candidate.blocker_count++]=s;};
        const auto gate=std::size_t(std::llround(context.sample_rate_hz*32e-6));
        const bool support=gate>=8 && m.gate_samples==gate && m.lag_samples==gate &&
            m.peak_offset<=samples && 2*gate<=samples-m.peak_offset && m.frequency_pairs==2*gate-1;
        candidate.offset=m.peak_offset;candidate.samples=support?2*gate:0;
        const auto& checked=evidence.candidates[index];
        candidate.marker_compatible=support && checked.pattern_consistent;
        candidate.status=!support || m.status!="measured"?"unavailable":
            !candidate.marker_compatible?"no_marker_match":!evidence.observed_quality_passed?"quality_rejected":
            checked.passband_status=="outside_declared_band"?"coverage_rejected":"unvalidated_candidate";
        if(!support)block("insufficient_contiguous_marker_support");
        if(!candidate.marker_compatible)block("marker_checks_not_passed");
        if(!evidence.observed_quality_passed)block("observed_quality_failed");
        if(checked.passband_status!="fits_declared_band")block(checked.passband_status=="outside_declared_band"?
            "outside_declared_passband":"usable_passband_unknown");
        block("full_symbol_duration_not_established");
        if(profile->slope>0)block("reported_20ms_recurrence_not_tested");
        block("signature_not_unique_to_family");
        block("receiver_profile_unqualified");
        block("independent_link_validation_missing");
    }
    return out;
}
} // namespace rfmon::cyclo
